package org.opengridseg.image;
public final class ExpandedRotation { private ExpandedRotation(){} public static RotatedImage rotate(FloatPlane source,double angle,Interpolation method){double a=Math.toRadians(angle),ca=Math.abs(Math.cos(a)),sa=Math.abs(Math.sin(a));int width=(int)Math.ceil((source.width()-1)*ca+(source.height()-1)*sa)+1,height=(int)Math.ceil((source.width()-1)*sa+(source.height()-1)*ca)+1;double scx=(source.width()-1)/2.0,scy=(source.height()-1)/2.0,rcx=(width-1)/2.0,rcy=(height-1)/2.0;FloatPlane out=new FloatPlane(width,height);double c=Math.cos(a),s=Math.sin(a);for(int y=0;y<height;y++)for(int x=0;x<width;x++){double u=x-rcx,v=y-rcy,sx=scx+c*u-s*v,sy=scy+s*u+c*v;out.set(x,y,CropExtractor.sample(source,sx,sy,method));}return new RotatedImage(out,angle,scx,scy,rcx,rcy,source.width(),source.height());} }
